// Input arrives as the `query` string: "invoiceTax, expectedTax" in dollars.
const nums = String(query).match(/-?\d+(?:\.\d+)?/g) || [];
if (nums.length < 2) {
  return JSON.stringify({ error: 'pass two numbers: invoiceTax, expectedTax' });
}
const invoiceTax = Number.parseFloat(nums[0]);
const expectedTax = Number.parseFloat(nums[1]);
const variance = Math.round((invoiceTax - expectedTax) * 100) / 100;
return JSON.stringify({ invoice_tax: invoiceTax, expected_tax: expectedTax, variance });

// Parse the agent's final decision the same way the CI assertion does:
// take the LAST balanced JSON object with an `action` field, so a stray
// JSON-ish snippet in the reasoning trace cannot fool the workflow.
// Mirrors evals/assertions/action_matches.mjs.
const VALID_ACTIONS = ['auto_approve', 'request_human_approval', 'reject_and_flag'];

function stripFences(text) {
  return text.replace(/```(?:json)?/gi, '').trim();
}

function balancedBlocks(text) {
  const blocks = [];
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') inString = true;
    else if (ch === '{') {
      if (depth === 0) start = i;
      depth++;
    } else if (ch === '}') {
      if (depth > 0) {
        depth--;
        if (depth === 0 && start >= 0) {
          blocks.push(text.slice(start, i + 1));
          start = -1;
        }
      }
    }
  }
  return blocks;
}

function extractDecision(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'object' && raw.action !== undefined) return raw;
  const text = stripFences(String(raw));
  if (!text) return null;
  const candidates = [text, ...balancedBlocks(text)];
  let best = null;
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      if (parsed && typeof parsed === 'object' && typeof parsed.action === 'string') best = parsed;
    } catch (e) {
      // not JSON, keep looking
    }
  }
  return best;
}

const agentOutput = $input.first().json.output;
const decision = extractDecision(agentOutput);

// The guardrail needs an amount. Prefer the structured amount the caller
// sent with the webhook; fall back to the first $ figure in the invoice
// text. Production callers should always send the structured field.
const webhookBody = $('Invoice received').first().json.body || {};
const invoiceText = String(webhookBody.invoice_text || '');
const extracted = invoiceText.match(/\$\s*([\d,]+(?:\.\d{1,2})?)/);
const amount =
  typeof webhookBody.amount === 'number'
    ? webhookBody.amount
    : extracted
      ? Number.parseFloat(extracted[1].replace(/,/g, ''))
      : null;

return [
  {
    json: {
      action: decision && VALID_ACTIONS.includes(decision.action) ? decision.action : 'unparseable',
      amount,
      amount_source: typeof webhookBody.amount === 'number' ? 'structured' : extracted ? 'regex_from_text' : 'unknown',
      po_match: decision ? decision.po_match === true : null,
      variance_amount: decision && typeof decision.variance_amount === 'number' ? decision.variance_amount : null,
      reasoning: decision && decision.reasoning ? String(decision.reasoning) : null,
      invoice_ref: webhookBody.invoice_ref || null,
      vendor: webhookBody.vendor || null,
      parse_ok: Boolean(decision && VALID_ACTIONS.includes(decision.action)),
      raw_output: agentOutput === undefined ? null : String(agentOutput),
    },
  },
];

// Build one INSERT with proper SQL escaping (single quotes doubled).
// Every branch of the workflow converges here: shadow mode logs everything,
// including guardrail breaches and unparseable output.
const d = $('Parse decision').first().json;
const mode = $env.AGENT_MODE ? String($env.AGENT_MODE) : 'shadow';

const esc = (v) => {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  return "'" + String(v).replace(/'/g, "''") + "'";
};

const sql = [
  'INSERT INTO agents.audit_log',
  '  (svc, mode, invoice_ref, vendor, amount, po_present, po_verified,',
  '   variance_amount, agent_action, agent_reasoning, raw_output)',
  'VALUES (',
  ["'svc_03'", esc(mode), esc(d.invoice_ref), esc(d.vendor), esc(d.amount), esc(d.po_match), esc(d.po_match), esc(d.variance_amount), esc(d.action), esc(d.reasoning), esc(d.raw_output)].join(', '),
  ');',
].join('\n');

return [{ json: { insert_sql: sql } }];
